package com.loja.checkout.pagamento;

import com.loja.checkout.service.Arredondamento;
import java.math.BigDecimal;
import org.springframework.stereotype.Component;

@Component("CARTAO")
public class CartaoPagamento implements FormaPagamento {

    private static final int PARCELAS_SEM_JUROS = 3;
    private static final double TAXA_JUROS_MENSAL = 0.0199;

    @Override
    public boolean parcelasPermitidas(int parcelas) {
        return parcelas >= 1 && parcelas <= 12;
    }

    @Override
    public boolean disponivelPara(BigDecimal totalPedido) {
        return true;
    }

    @Override
    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
        if (parcelas <= PARCELAS_SEM_JUROS) {
            BigDecimal valorParcela = Arredondamento.centavos(
                    totalPedido.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
            return new ResultadoPagamento(totalPedido, valorParcela, BigDecimal.ZERO);
        }

        double total = totalPedido.doubleValue();
        double fatorDesconto = 1 - Math.pow(1 + TAXA_JUROS_MENSAL, -parcelas);
        double parcelaComJuros = total * TAXA_JUROS_MENSAL / fatorDesconto;
        BigDecimal valorParcela = Arredondamento.centavos(BigDecimal.valueOf(parcelaComJuros));
        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
        BigDecimal ajuste = totalFinal.subtract(totalPedido);
        return new ResultadoPagamento(totalFinal, valorParcela, ajuste);
    }
}

