                .andExpect(status().isOk())
                .andReturn()
                .getResponse()
                .getContentAsString();
        return objectMapper.readValue(json, ResumoResponse.class);
    }

    private String executarComErro(ResumoRequest request) throws Exception {
        String json = mockMvc.perform(post("/checkout/resumo")
