1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.service.Arredondamento;
4	import java.math.BigDecimal;
5	import org.springframework.stereotype.Component;
6	
7	@Component("CARTAO")
8	public class CartaoPagamento implements FormaPagamento {
9	
10	    private static final int PARCELAS_SEM_JUROS = 3;
11	    private static final double TAXA_JUROS_MENSAL = 0.0199;
12	
13	    @Override
14	    public boolean parcelasPermitidas(int parcelas) {
15	        return parcelas >= 1 && parcelas <= 12;
16	    }
17	
18	    @Override
19	    public boolean disponivelPara(BigDecimal totalPedido) {
20	        return true;
21	    }
22	
23	    @Override
24	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
25	        if (parcelas <= PARCELAS_SEM_JUROS) {
26	            BigDecimal valorParcela = Arredondamento.centavos(
27	                    totalPedido.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
28	            return new ResultadoPagamento(totalPedido, valorParcela, Arredondamento.ZERO);
29	        }
30	
31	        double total = totalPedido.doubleValue();
32	        double fatorDesconto = 1 - Math.pow(1 + TAXA_JUROS_MENSAL, -parcelas);
33	        double parcelaComJuros = total * TAXA_JUROS_MENSAL / fatorDesconto;
34	        BigDecimal valorParcela = Arredondamento.centavos(BigDecimal.valueOf(parcelaComJuros));
35	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
36	        BigDecimal ajuste = totalFinal.subtract(totalPedido);
37	        return new ResultadoPagamento(totalFinal, valorParcela, ajuste);
38	    }
39	}
