import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;

public class Calc {
    public static void main(String[] args) {
        MathContext mc = new MathContext(20, RoundingMode.HALF_EVEN);
        BigDecimal total = new BigDecimal("429.40");
        BigDecimal taxa = new BigDecimal("0.0199");
        int n = 4;
        BigDecimal fator = BigDecimal.ONE.add(taxa).pow(n, mc);
        BigDecimal desconto = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, mc));
        BigDecimal parcela = total.multiply(taxa).divide(desconto, mc).setScale(2, RoundingMode.HALF_EVEN);
        BigDecimal totalFinal = parcela.multiply(BigDecimal.valueOf(n));
        BigDecimal ajuste = totalFinal.subtract(total);
        System.out.println("parcela=" + parcela);
        System.out.println("totalFinal=" + totalFinal);
        System.out.println("ajuste=" + ajuste);

        // also leve3pague2 multi item test calc
        // meia qty 7 (floor7/3=2)*19.90=39.80, camiseta qty 6 (floor6/3=2)*79.90=159.80
        BigDecimal descontoLeve = new BigDecimal("19.90").multiply(BigDecimal.valueOf(2))
                .add(new BigDecimal("79.90").multiply(BigDecimal.valueOf(2)));
        System.out.println("descontoLeve=" + descontoLeve);
    }
}
